func MergeSampleDocs(docs []bson.M) map[string]interface{} {
	out := make(map[string]interface{})
	for _, d := range docs {
		for k, v := range d {
			if v == nil {
				if _, seen := out[k]; !seen {
					out[k] = nil
				}
				continue
			}
			out[k] = v
		}
	}
	return out
}

